#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum OtpBytesError<E>{InvalidRange,Read(E)}
pub trait OtpWordReader{type Error;fn read_words(&mut self,secure:bool,word_addr:u16,out:&mut[u32])->Result<(),Self::Error>;}
pub fn otp_read_bytes<R:OtpWordReader>(r:&mut R,secure:bool,offset:u16,out:&mut[u8])->Result<(),OtpBytesError<R::Error>>{let n=out.len();if n==0||n>0x1000||offset as usize>0x0fff||offset as usize+n>0x1000{return Err(OtpBytesError::InvalidRange)}let first=offset as usize/4;let end=(offset as usize+n-1)/4;let mut word=first;let mut out_pos=0usize;let skip=offset as usize&3;let mut first_chunk=true;let mut tmp=[0u32;16];while word<=end{let count=core::cmp::min(16,end-word+1);r.read_words(secure,word as u16,&mut tmp[..count]).map_err(OtpBytesError::Read)?;let bytes=unsafe{core::slice::from_raw_parts(tmp.as_ptr()as*const u8,count*4)};let begin=if first_chunk{skip}else{0};let take=core::cmp::min(bytes.len()-begin,n-out_pos);out[out_pos..out_pos+take].copy_from_slice(&bytes[begin..begin+take]);out_pos+=take;word+=count;first_chunk=false}Ok(())}
pub const fn secure_boot_marker(first:u8,second:u8)->u8{if first.count_ones()>3||second.count_ones()>3{0xff}else{0}}
#[cfg(test)]mod tests{use super::*;struct R;impl OtpWordReader for R{type Error=();fn read_words(&mut self,_:bool,a:u16,o:&mut[u32])->Result<(),()>{for(i,v)in o.iter_mut().enumerate(){*v=(a as u32+i as u32)*0x04040404+0x03020100}Ok(())}}#[test]fn bytes(){let mut r=R;let mut o=[0u8;7];otp_read_bytes(&mut r,false,3,&mut o).unwrap();assert_eq!(o.len(),7);assert_eq!(secure_boot_marker(0x0f,0),0xff);assert_eq!(secure_boot_marker(7,7),0);}}
